/* Body bg */
.post-type-archive-tf_tours,
.post-type-archive-tf_hotel,
.post-type-archive-tf_apartment,
.tax-hotel_location,
.tax-tour_destination,
.tax-apartment_location,
.page-template-tf-search,
.single-tf_apartment,
.single-tf_hotel,
.single-tf_tours {
    background-color: $color-white;
}

.section-heading {
    font-size: 1.75rem;
    margin-bottom: 15px;
    font-weight: 600;
    color: $color-heading;
}

h3.section-heading {
    font-size: 1.75rem;
    color: $color-heading;
}

.fancybox-navigation .fancybox-button--arrow_left>div,
.fancybox-navigation .fancybox-button--arrow_right>div {
    background-color: $color-heading;
}

.tf-title-area {
    h1 {
        font-size: 2.188rem;
        margin-top: 0;
        margin-bottom: 6px;
        color: $color-heading;
        overflow: hidden;
        text-overflow: ellipsis;
        display: -webkit-box;
        -webkit-line-clamp: 2;
        -webkit-box-orient: vertical;

        @media #{$max768} {
            font-size: 1.75rem;
            line-height: 1.3;
        }
    }

    .tf-title-wrap {
        display: flex;
        justify-content: space-between;
        gap: 20px;

        @media #{$max768} {
            display: block;
        }

        .tf-title-left {
            flex: 1;

            span.post-type {
                background: $color-primary;
                color: $color-white;
                padding: 0 10px;
                font-size: 0.813rem;
                border-radius: 25px;
                margin-bottom: 5px;
                display: inline-block;
            }

            .tf-map-link {

                i,
                svg {
                    margin-right: 4px;
                }

                .tf-d-ib {
                    overflow: hidden;
                    text-overflow: ellipsis;
                    display: -webkit-box;
                    -webkit-line-clamp: 2;
                    -webkit-box-orient: vertical;
                }

                a {
                    color: $color-primary;
                }
            }
        }

        .tf-title-right {
            display: flex;
            align-items: center;
            column-gap: 5px;

            @media #{$max768} {
                margin-top: 15px;
            }

            .tf-wishlist-button {
                font-size: 1.5rem;
                cursor: pointer;
                margin: 0 5px 0 0;
                line-height: 1;
            }
        }
    }
}

.tf-single-rating {
    line-height: 1;
    font-size: 1rem;
    cursor: pointer;
    z-index: 999;
    display: inline-block;
    background: rgba(19, 55, 116, 0.6);
    border: 1px solid rgba(255, 255, 255, 0.08);
    box-sizing: border-box;
    padding: 8px;
    color: $color-white;
    border-radius: 4px;
    position: relative;

    @media #{$max768} {
        font-size: 0.875rem;
        padding: 6px;
    }

    i {
        font-size: 0.875rem;
        color: $color-primary;
    }

    span {
        margin: 0 3px 0 5px;
        font-weight: 700;
        font-size: 1.125rem;

        @media #{$max768} {
            font-size: 0.875rem;
        }
    }
}

.tf_room_name_inner {
    padding-top: 20px;
}

.tf-slick-slider {
    position: relative;
    display: block;
    box-sizing: border-box;
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;
    -webkit-touch-callout: none;
    -khtml-user-select: none;
    touch-action: pan-y;
    -webkit-tap-highlight-color: transparent;

    .slick-track {
        transform: translate3d(0, 0, 0);
        position: relative;
        top: 0;
        left: 0;
        display: block;
        margin-left: auto;
        margin-right: auto;

        &:before {
            display: table;
            content: "";
        }

        &:after {
            display: table;
            content: "";
            clear: both;
        }
    }

    .slick-list {
        transform: translate3d(0, 0, 0);
        position: relative;
        display: block;
        overflow: hidden;
        margin: 0;
        padding: 0;
        margin-left: -5px !important;
        margin-right: -5px !important;

        &:focus {
            outline: none;
        }
    }

    .slick-slide {
        margin-left: 5px;
        margin-right: 5px;

        img {
            display: block;
        }
    }

    &.slick-initialized {
        .slick-slide {
            display: block;

            @media #{$max768} {
                margin: 0px !important;
            }
        }
    }
}

.tf-suggestion-wrapper .tf-slider-items-wrapper {
    .slick-track {
        display: -webkit-box !important;
        display: -ms-flexbox !important;
        display: flex !important;

        @media #{$max768} {
            margin-bottom: 15px !important;
        }

        >div {
            height: auto;
            min-height: -webkit-fill-available !important;
            display: -webkit-box !important;
            display: -ms-flexbox !important;
            display: flex !important;
            -webkit-box-align: end !important;
            -ms-flex-align: end !important;
            align-items: flex-end !important;
        }

        .tf-slider-content {
            margin-top: 200px !important;
        }
    }

    .tf-slider-item {
        height: auto;
    }
}

.tf_form-row {
    .tf_label-row {
        margin-bottom: 15px;
        display: block;
    }

    .tf_form-inner {
        svg {
            width: 20px;
            height: 20px;
        }

        i {
            font-size: 18px;
        }

        input[type=text] {
            width: 100%;
            background: transparent;
            border: 0;
            box-shadow: none;
            height: 45px;
            margin: 0px;

            &:focus {
                background: transparent;
                border: 0;
                outline: 0;
            }
        }

        select {
            width: 100%;
            background: transparent;
            border: 0;
            box-shadow: none;
            height: 45px;
            -webkit-appearance: none;
            appearance: none;
            -moz-appearance: none;
            cursor: pointer;
            font-size: 0.875rem;
            color: $color-text;

            &:focus {
                background: transparent;
                border: 0;
                outline: 0;
            }
        }
    }
}

.tf-hotel-side-booking {
    .tf_form-inner {
        position: relative;
        display: grid;
        padding: 0;
        background: $color-filling-bg;
        grid-template-columns: 38px auto;
        @include align-items(center);
        justify-items: center;
        padding-left: 5px;

        i {
            color: $color-text;
            font-size: 1rem;

            &:last-child {
                position: absolute;
                right: 12px;
            }
        }
    }

    #check-in-out-date {
        min-width: 150px;
    }
}

.tf_acrselection-wrap {
    position: absolute;
    top: 100%;
    right: 0;
    margin-top: 0px;
    background: $color-filling-fg;
    padding: 16px 20px 8px;
    min-width: 250px;
    border-radius: 4px;
    z-index: 9999;
    width: 100%;
    display: none;
}

.tf_acrselection {
    @include flexbox();
    @include align-items(center);
    @include justify-content(space-between);
    margin-bottom: 16px;

    .acr-select {
        @include flexbox();
        @include align-items(center);
        width: 125px;

        input[type=number] {
            width: 50px;
            padding: 0px;
            margin: 0px;
            border: 0px;
            box-shadow: none;
            background: transparent;
            text-align: center;
            appearance: textfield !important;
            -moz-appearance: textfield !important;

            &:focus {
                outline: 0;
            }
        }
    }

    .acr-dec {
        width: 30px;
        height: 30px;
        -webkit-user-select: none;
        -moz-user-select: none;
        -ms-user-select: none;
        user-select: none;
        color: $color-brand-dark;
        border-color: $color-brand-dark;
        border: 1px solid $color-brand-dark;
        border-radius: 50%;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        text-align: left;
        padding: 7px 15px;
        cursor: pointer;
        text-decoration: none;
        box-sizing: border-box;
        vertical-align: middle;
        position: relative;
        min-height: 36px;
        min-width: 36px;
        font-size: 0.875rem;
        font-weight: 500;
        line-height: 1.5;

        &:hover {
            color: $color-text;
            border-color: $color-text;
        }
    }

    .acr-inc {
        width: 30px;
        height: 30px;
        -webkit-user-select: none;
        -moz-user-select: none;
        -ms-user-select: none;
        user-select: none;
        color: $color-brand-dark;
        border-color: $color-brand-dark;
        border: 1px solid $color-brand-dark;
        border-radius: 50%;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        text-align: left;
        padding: 7px 15px;
        cursor: pointer;
        text-decoration: none;
        box-sizing: border-box;
        vertical-align: middle;
        position: relative;
        min-height: 36px;
        min-width: 36px;
        font-size: 0.875rem;
        font-weight: 500;
        line-height: 1.5;

        &:hover {
            color: $color-text;
            border-color: $color-text;
        }
    }
}

.tf-search-form-field-icon {
    margin-right: 8px;
}

.tf_destination-wrap {
    border-right: 1px solid $color-border-lite;
    border-left: 0;
    display: table-cell;
    vertical-align: middle;
    min-width: 150px;
    width: 25%;

    @media #{$max768} {
        width: 100%;
        display: block;
        padding: 10px;
        border-bottom: 1px solid $color-gray;
    }

    .tf_input-inner {
        padding: 0 15px;

        @media #{$max768} {
            padding: 0 10px;
        }
    }

    .ui-menu-item {
        &:before {
            content: "\f3c5";
            font-weight: 900;
            font-family: "Font Awesome 5 Free";
            float: left;
            font-size: 0.938rem;
            line-height: 1.5;
            margin-right: 5px;
        }
    }
}

#tf_car_booking {
    .tf_homepage-booking {
        @media #{$max991} {
            display: inherit;
            height: auto;
        }
    }

    .tf_destination-wrap {
        width: auto;

        @media #{$max991} {
            padding: 10px 5px;
            width: 100%;
            display: block;
            border-bottom: 1px solid gray;
        }
    }

    .tf_submit-wrap {
        @media #{$max991} {
            width: 100%;
            display: block;
            border-radius: 0 0 8px 8px;
        }
    }
}

.tf_selectdate-wrap {
    border-right: 1px solid $color-border-lite;
    display: table-cell;
    vertical-align: middle;
    padding: 0 15px;
    width: 20%;
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;

    @media #{$max768} {
        width: 100%;
        display: block;
        padding: 10px 20px;
        border-bottom: 1px solid $color-gray;

        &.tf_more_info_selections {
            padding: 20px;
            position: relative;
            cursor: pointer;
        }
    }

    .tf_input-inner {
        @include flexbox();
        @include align-items(center);
        cursor: pointer;
    }
}

.tf_selectperson-wrap {
    border-right: 1px solid $color-border-lite;
    display: table-cell;
    vertical-align: middle;
    width: auto;
    position: relative;
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;

    @media #{$max768} {
        width: 100%;
        display: block;
        padding: 20px 0;
        border-bottom: 1px solid $color-gray;
    }

    .tf_input-inner {
        @include flexbox();
        @include align-items(center);
        cursor: pointer;
    }

    .person-sep {
        padding: 0 8px;
        position: relative;
        white-space: nowrap;

        &:after {
            content: "";
            position: absolute;
            height: 2px;
            background: $color-brand-lite;
            width: 2px;
            left: 0;
            top: 0px;
            z-index: 2;
            right: 0;
            text-align: center;
            margin: 0 auto;
        }
    }

    .adults-text {
        white-space: nowrap;
    }

    .child-text {
        white-space: nowrap;
    }

    .room-text {
        white-space: nowrap;
    }

    .infant-text {
        white-space: nowrap;
    }
}

.tf_submit-wrap {
    border-right: 0;
    border-radius: 0 8px 8px 0;
    background: $color-primary;
    width: 15%;
    display: table-cell;
    vertical-align: middle;

    @media #{$max768} {
        width: 100%;
        display: block;
        border-radius: 0 0 8px 8px;
    }

    button {
        width: 100%;
        height: 100%;
        border-radius: 0 8px 8px 0;
        padding: 20px 20px;
    }
}

.tf-review-form-container {
    min-width: 800px;
    padding: 0;
    margin: 0;
    background: $color-white;

    @media #{$max1024} {
        min-width: 500px;
    }

    @media #{$max768} {
        min-width: auto;
    }

    .logged-in-as {
        display: none;
    }

    .tf-rating-wrapper {
        display: grid;
        grid-template-columns: calc(50% - 20px) calc(50% - 20px);
        column-gap: 40px;
        row-gap: 15px;
        margin: 0 0 80px 0;

        @media #{$max768} {
            grid-template-columns: 100%;
        }

        .tf-form-single-rating {
            display: grid;
            grid-template-columns: auto auto;
            justify-content: space-between;
            align-items: center;
            column-gap: 15px;

            label {
                color: $color-text;
                font-weight: 500;
                font-size: 1rem;
                line-height: 1;
                text-transform: capitalize;
            }
        }
    }

    .tf-form-single-rating {
        .error {
            color: $color-danger;
        }

        .ratings-container {
            line-height: 1;
            unicode-bidi: bidi-override;
            direction: rtl;

            label {
                padding: 0;
                margin: 0;
                height: auto;
                line-height: 1;
                color: transparent;
            }

            >input {
                display: none;
            }
        }

        .ratings-container.star10 {
            width: 220px;
        }

        .ratings-container.star5 {
            width: 110px;
        }
    }

    .ratings-container {
        >input+label {
            text-indent: -9999px;
            font-family: "Font Awesome 5 Free";
            display: inline-block;
            overflow: hidden;
            width: 22px;
            white-space: nowrap;
            cursor: pointer;
            color: transparent;

            &:before {
                text-indent: 9999px;
                display: inline-block;
                content: "\f005";
                color: $color-warning;
                font-size: 1rem;
                font-weight: 400;
            }

            &:hover~label {
                &:before {
                    content: "\f005";
                    color: $color-warning;
                    font-weight: 900;
                }
            }

        }

        >.star-cb-clear+label {
            text-indent: 9999px;
            text-indent: -9999px;
            width: 0.5em;
            margin-left: -0.5em;

            &:before {
                width: 0.5em;
            }
        }

        >input {
            &:checked~label {
                &:before {
                    content: "\f005";
                    color: $color-warning;
                    font-weight: 900;
                }
            }
        }

        &:hover {
            >input+label {

                &:hover~label {
                    &:before {
                        content: "\f005";
                        color: $color-warning;
                        font-weight: 900;
                    }
                }

                &:hover {
                    &:before {
                        content: "\f005";
                        color: $color-warning;
                        font-weight: 900;
                    }
                }
            }
        }
    }

    .review-desc {
        textarea {
            background: $color-gray-light;
            border: 1px solid $color-border-lite;
            border-radius: 4px;
            padding: 16px 8px 16px 16px;
            height: 160px;
            outline: none;
            color: $color-text;
            box-shadow: none;
            width: 100%;

            &::placeholder {
                color: $color-text;
            }
        }
    }

    .tf-visitor-info {
        display: grid;
        grid-template-columns: calc(50% - 20px) calc(50% - 20px);
        column-gap: 40px;
        margin: 16px 0 0 0;

        input {
            background: $color-gray-light;
            border: 1px solid $color-border-lite;
            box-sizing: border-box;
            border-radius: 4px;
            height: 56px;
            padding: 16px 8px 16px 16px;
            outline: none;
            color: $color-text;
            box-shadow: none;
            width: 100%;
        }

        .error {
            color: $color-danger;
        }
    }

    .tf-review-submit {
        margin: 25px 0 0 0;
    }

    form.tf-review-form {
        @media #{$max1024} {
            gap: 20px;
        }
    }
}

#tf-rating-modal {
    .tf-modal-content {
        padding: 40px;
    }

    .logged-in-as {
        text-align: center;
        margin-bottom: 25px;
    }
}

.tf-review-container {
    .no-comments {
        display: none;
    }

    .tf-total-review {
        display: grid;
        grid-template-columns: auto auto;
        justify-content: space-between;
        align-items: center;
        margin: 0 0 25px 0;

        .tf-total-average {
            display: grid;
            grid-template-columns: auto auto;
            align-items: center;

            div {
                width: 60px;
                height: 60px;
                background: $color-primary;
                border-radius: 4px;
                display: flex;
                flex-direction: row;
                justify-content: center;
                align-items: center;
                padding: 16px;
                color: $color-white;
                font-weight: 600;
                font-size: 1.5rem;
                line-height: 1.3;
            }

            span {
                color: $color-text;
                font-weight: 400;
                font-size: 1rem;
                line-height: 1.5;
                margin: 0px 16px;
            }
        }
    }

    .tf-review-progress-bar {
        background: $color-filling-fg;
        display: grid;
        grid-template-columns: calc(50% - 20px) calc(50% - 20px);
        column-gap: 40px;
        row-gap: 20px;
        padding: 24px;
        border: 1px solid $color-filling-fg;
        box-sizing: border-box;
        border-radius: 4px;
        margin: 0 0 25px 0;

        @media (min-width: 768px) and (max-width: 991px) {
            grid-template-columns: auto;
        }

        @media #{$max768} {
            grid-template-columns: auto;
        }

        .tf-single {
            display: grid;
            grid-template-columns: calc(50% - 15px) calc(50% - 15px) 30px;
            align-items: center;

            .tf-text {
                text-align: left;
                color: $color-text;
                font-weight: 400;
                font-size: 0.875rem;
                line-height: 1;
                text-transform: capitalize;
            }

            .tf-p-bar {
                width: 100%;
                height: 7px;
                background: $color-filling-fg;
                border-radius: 4px;
                position: relative;
                overflow: hidden;

                .percent-progress {
                    position: absolute;
                    width: 0;
                    background-color: $color-primary;
                    height: 100%;
                    transition: width 1s ease-in-out;
                }
            }

            .tf-p-b-rating {
                text-align: right;
                font-weight: 500;
                font-size: 0.875rem;
                line-height: 1;
                color: $color-text;
            }
        }
    }

    .no-review {
        h4 {
            text-align: center;
            color: $color-heading;
            margin-bottom: 10px;
            font-size: 1.25rem;
        }

        .btn-styled {
            padding: 18px 20px;
        }
    }
}

.tf-single-review {
    display: grid;
    grid-template-columns: calc(50% - 10px) calc(50% - 10px);
    column-gap: 20px;
    row-gap: 40px;

    @media (min-width: 768px) and (max-width: 991px) {
        grid-template-columns: auto;
    }

    @media #{$max768} {
        grid-template-columns: auto;
    }

    &.tf-reviews-slider ul.slick-dots {
        margin: 0;
    }

    .tf-single-details {
        display: grid;
        grid-template-columns: 56px calc(100% - 72px);
        column-gap: 16px;
        background: $color-filling-fg;
        padding: 25px 25px 35px;
        border-radius: 4px;
    }

    .tf-review-avatar {
        width: 56px;
        height: 56px;
        border-radius: 50%;
        overflow: hidden;
    }

    .tf-review-details {
        .tf-name {
            font-weight: 500;
            font-size: 1.125rem;
            line-height: 1;
            color: $color-heading;
            margin: 0 0 8px 0;
            text-transform: capitalize;
        }

        .tf-date {
            font-weight: 400;
            font-size: 0.75rem;
            line-height: 1;
            color: $color-text;
            letter-spacing: 0.2px;
            margin: 0 0 8px;
        }

        .tf-rating-stars {
            display: grid;
            grid-template-columns: auto auto;
            column-gap: 5px;
            align-items: center;
            justify-content: start;
            line-height: 1;

            i {
                color: $color-primary;
                font-size: 0.625rem;
                height: 14px;
            }
        }

        .tf-description {
            font-weight: 400;
            font-size: 0.875rem;
            line-height: 1.5;
            color: $color-text;
            margin: 8px 0 0 0;

            p {
                margin-bottom: 0;
            }
        }
    }
}

.tf-review-pending {
    text-align: center;
    font-size: 1rem;
    font-style: italic;
    background: $color-white;
    border-radius: 4px;
    padding: 10px 10px;
    color: $color-text;
    margin: 30px 0 10px 0;
}

.tf-ask-question {
    background: $color-filling-fg;
    padding: 30px;
    border-radius: 4px;
    flex: 2;
    text-align: center;

    @media #{$max768} {
        max-width: 450px;
        margin: auto;
    }

    .default-enquiry-title-section {
        @include flexbox();
        justify-content: center;
        align-items: baseline;

        h3 {
            font-size: 1.375rem;
            color: $color-heading;
            margin-bottom: 10px;
        }

        i {
            font-weight: 900;
            padding-right: 10px;
            font-size: 1.375rem;
            color: $color-primary;
        }
    }
}

.tf-slider-item {
    border: 12px solid $color-filling-fg;
    border-radius: 4px;
    height: 450px;
    padding: 20px;
    display: flex;
    align-items: flex-end;
    margin: 0 15px 15px;
    background-repeat: no-repeat;
    background-size: cover;
    background-position: center center;
    margin-left: 0;

    @media only screen and (min-width: 768px) and (max-width: 970px) {
        border: 7px solid $color-white;
        height: 300px;
        padding: 15px;
